// Turns an API order event into a WhatsApp text for the staff phone
const { event, data } = $input.first().json.body;
const order = data.order ?? data;
const items = (order.items ?? []).map(i => `• ${i.quantity} x ${i.productName}`).join('\n');
const money = n => '$ ' + Number(n).toLocaleString('es-CO');
const head = {
  'order.created': order.status === 'Received' ? '🟢 Pedido nuevo' : '🕓 Pedido esperando pago',
  'order.payment_submitted': '🧾 Comprobante recibido: revisar en el panel',
  'order.confirmed': '✅ Pago aprobado: pedido a cocina',
  'order.delayed': `⏰ Pedido demorado (${data.minutesWaiting} min) y aún no sale`,
  'order.escalated': `⚠️ Admin: el pedido sigue sin salir (${data.minutesWaiting} min)`,
  'order.updated': `🔄 Pedido actualizado: ${order.status}`
}[event] ?? event;
const text = `${head}\nPedido ${order.code} · ${order.customerName} (${order.customerPhone})\nSector: ${order.sectorName}\n${items}\nTotal: ${money(order.total)} · Pago: ${order.paymentMethod === 'Cash' ? 'efectivo' : 'transferencia'}`;
return [{ json: { text, event } }];
